} from 'react-native';
import { Audio } from 'expo-av';
import * as Speech from 'expo-speech';
import { StatusBar } from 'expo-status-bar';

// ---- Simple avatar presets (no extra files needed) ----
const AVATAR_PRESETS = [
  {
    id: 'shadow_male',
    skinTone: '#F2C6A0',
    outfitColor: '#10B981',
    backgroundColor: '#111827',
    label: 'Shadow Male',
  },
  {
    id: 'shadow_female',
    skinTone: '#D78C5C',
    outfitColor: '#EC4899',
    backgroundColor: '#1F2937',
    label: 'Shadow Female',
  },
  {
    id: 'shadow_neutral',
    skinTone: '#9CA3AF',
    outfitColor: '#6366F1',
    backgroundColor: '#111827',
    label: 'Shadow Neutral',
  },
  {
    id: 'cartoon_boy',
    skinTone: '#FCD34D',
    outfitColor: '#3B82F6',
    backgroundColor: '#0F172A',
    label: 'Cartoon Boy',
  },
  {
    id: 'cartoon_girl',
    skinTone: '#F9A8D4',
    outfitColor: '#8B5CF6',
    backgroundColor: '#111827',
    label: 'Cartoon Girl',
  },
];

const DEFAULT_AVATAR = AVATAR_PRESETS[2]; // shadow_neutral

// ---- Simple AvatarPicker inside same file ----
function AvatarPicker({ value, onChange }) {
  return (
    <View>
      <Text style={styles.sectionTitle}>Choose Your Look</Text>
      <View style={styles.avatarRow}>
        {AVATAR_PRESETS.map((preset) => {
          const selected = preset.id === value.id;
          return (
            <TouchableOpacity
              key={preset.id}
              style={[
                styles.avatarBox,
                { backgroundColor: preset.backgroundColor },
                selected && styles.avatarSelected,
              ]}
              onPress={() => onChange(preset)}
            >
              <View
                style={[
                  styles.avatarHead,
                  { backgroundColor: preset.skinTone },
                ]}
              />
              <View
                style={[
                  styles.avatarBody,
                  { backgroundColor: preset.outfitColor },
                ]}
              />
              <Text style={styles.avatarLabel}>{preset.label}</Text>
            </TouchableOpacity>
          );
        })}
      </View>
    </View>
